import { MakeLogicType, actions, kea, path, reducers, selectors } from 'kea'

import { initKeaTests } from '~/test/init'

let computations = 0

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cacheTestLogicValues {
    value: number
    doubled: number
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cacheTestLogicActions {
    setValue: (value: number) => {
        value: number
    }
}

export type cacheTestLogicType = MakeLogicType<cacheTestLogicValues, cacheTestLogicActions>

const cacheTestLogic = kea<cacheTestLogicType>([
    path(['lib', 'reselectPrimitiveCache', 'cacheTestLogic']),
    actions({ setValue: (value: number) => ({ value }) }),
    reducers({ value: [0, { setValue: (_, { value }: { value: number }) => value }] }),
    selectors({
        doubled: [
            (s) => [s.value],
            (value: number): number => {
                computations++
                return value * 2
            },
        ],
    }),
])

// Guards patches/reselect@5.2.0.patch: kea builds every selector on reselect's weakMapMemoize,
// which keeps primitive input values in a plain Map. Unpatched, a long-lived tab grows that Map
// until V8 refuses a larger one and the app throws "Map maximum size exceeded".
describe('reselect primitive cache bound', () => {
    beforeEach(() => {
        initKeaTests()
        computations = 0
        cacheTestLogic.mount()
    })

    it('stops growing once enough distinct values arrive, and still memoizes repeats', () => {
        cacheTestLogic.actions.setValue(1)
        expect(cacheTestLogic.values.doubled).toBe(2)
        expect(cacheTestLogic.values.doubled).toBe(2)
        expect(computations).toBe(1)

        for (let value = 100; value < 2100; value++) {
            cacheTestLogic.actions.setValue(value)
            expect(cacheTestLogic.values.doubled).toBe(value * 2)
        }
        const computationsBeforeReuse = computations

        cacheTestLogic.actions.setValue(1)
        expect(cacheTestLogic.values.doubled).toBe(2)
        expect(computations).toBe(computationsBeforeReuse + 1)
    })
})
